import{_ as l,b as d,c as i,d as a,t as v,C as o,u as f}from"./index-I5uTs6b4.js";const p={class:"level-page"},n={class:"level-content"},u={class:"level-title"},r={__name:"Level5",props:{id:{type:String,required:!0}},setup(t){const e=f();function s(){sessionStorage.setItem("skipIntro","1"),e.push("/")}return(h,c)=>(d(),i("div",p,[a("button",{class:"back-btn",onClick:s},"← Back to Index"),a("div",n,[a("h1",u,"SI-"+v(t.id),1),c[0]||(c[0]=o('<p class="level-name" data-v-cc560f0e>&quot;冷却，直至荒凉&quot;</p><div class="section" data-v-cc560f0e><h2 data-v-cc560f0e>生存难度：等级 4</h2><div class="difficulty" data-v-cc560f0e><ul class="class-list" data-v-cc560f0e><li data-v-cc560f0e><span class="class-bullet unsafe" data-v-cc560f0e></span> 不安全</li><li data-v-cc560f0e><span class="class-bullet stable" data-v-cc560f0e></span> 较稳定</li><li data-v-cc560f0e><span class="class-bullet entity" data-v-cc560f0e></span> 实体数量多</li></ul></div></div><div class="section" data-v-cc560f0e><h2 data-v-cc560f0e>层级外观</h2><p data-v-cc560f0e>SI-5 被描述为一个盆地中的&quot;废弃&quot;工业基地，由于 SI-5 的舒张效应，勘测队始终无法接近层级外围的山脉，所以当前认定 SI-5 的面积无穷大。层级中央是一座建在自然水系旁边的、看上去已经服役许久的双曲线冷却塔，外围则是无尽的厂房和工业设施。该层级长期处于类似于雾霾的压抑天气中，但是空气质量仍然优良，工业区刺鼻的空气被一种带有清淡烟味的潮湿气体取代。</p><p data-v-cc560f0e>经过勘测队的调查，该层级看上去处于&quot;废弃状态&quot;，厂房墙漆脱落、大门半掩、内部设施老化，但是所有工业设施都在以一个较低的速率持续运行，且整体没有继续衰退的迹象。同时，层级中工业区内的树木的树干焦黑，叶片呈棕红色，但仍处于存活状态。水系中能发现小型鱼类实体等生命存在，河流上有星星点点的小船，大多数是空空如也的。</p><p data-v-cc560f0e>中央的冷却塔外漆已尽数脱落，露出内部的砖石，外侧的爬梯也锈迹斑斑，但它依旧苟延残喘地履行着职责：塔顶慢悠悠地吐着白雾，塔底的喷淋头向水池释放&quot;热水&quot;，成为了这个空间里为数不多的声源。基于种种勘测结果，最终得出的结论是：该层级的生态和工业运转在未知效应下形成了一种特殊的平衡状态。</p><p class="attribution" data-v-cc560f0e>——勘测官 L 的行动日志</p></div><div class="section" data-v-cc560f0e><h2 data-v-cc560f0e>实体情况</h2><p data-v-cc560f0e>该层级实体数量多，大多数为悲尸、成年无面灵和猎犬。但它们都不活跃，只是自顾自地在厂房之间穿梭，无面灵有时会驾着小船在河流湖泊上游荡，猎犬更倾向于趴在大门口或者树底下肢团伪装的灌木旁。流浪者在不产生较大噪音（比工业设备噪音和喷淋头水声大）和不使用较亮光源的情况下不容易被攻击。</p><p data-v-cc560f0e>无名之火和笑魇不会在该层级出现，布拉格碎片在进入该层级后会变成灰色，钝人不会选择隔墙攻击流浪者，派对客不喜欢这里。</p></div><div class="section" data-v-cc560f0e><h2 data-v-cc560f0e>探索记录</h2><p data-v-cc560f0e>流浪者进入该层级时大概率会在冷却塔下，此时可以通过塔下承重柱的空隙看到塔底的喷淋系统。经检测，喷淋的液体为液态痛苦和杏仁水的混合稀溶液。由于勘测队在冷却塔附近的厂房中发现了杏仁水，故推测冷却塔的一个作用为分离液态痛苦和杏仁水，但是液态痛苦的去处仍然未知。</p><p data-v-cc560f0e>从中心向外探索，会发现不同功能的厂房。厂房被专门化地用于生产特定的一种工业品，设备会以一个低速率、高效率的模式生产普通工业品甚至火盐、皇家口粮等较稀有物品，但产量低得令人绝望。大多数烟气会被收集起来压缩为碳等较低级的工业品，这使得该层级的空气质量得以提升。层级内流水的成分为极稀的杏仁水，来自于冷却塔顶的蒸汽。</p><p class="quote" data-v-cc560f0e>&quot;这个层级整体就给人一种半死不活的感觉，无聊透顶！&quot;</p><p class="attribution" data-v-cc560f0e>——某位勘测员看着从自己面前若无其事地溜过去的悲尸，小声抱怨道。</p></div><div class="section" data-v-cc560f0e><h2 data-v-cc560f0e>入口与出口</h2><h3 class="sub-heading" data-v-cc560f0e>入口</h3><ul class="entry-list" data-v-cc560f0e><li data-v-cc560f0e>从 SI-4 迷宫尽头的红顶洋房后门离开进入 SI-5。</li><li data-v-cc560f0e>在序号 &gt;5 的层级中死亡会以特殊的悲尸形态进入冷却塔内部（次数有限，因人而异）。</li><li data-v-cc560f0e>在任意 5 以外的层级中找到一把周围有小矩形样式粒子效果的灰色锤子并用其敲击任意平面以进入厂房（这会产生较大的噪音）（锤子数量有限但具体数量和分布情况未知）。</li><li data-v-cc560f0e>兼容特殊的切入方式。</li></ul><h3 class="sub-heading" data-v-cc560f0e>出口</h3><p data-v-cc560f0e>适当地放下一些包袱吧，慢慢遛一遛，只要你想，总能出去的。</p><p class="hint" data-v-cc560f0e>（怀有离开的念头，并保持静默状态探索一段时间后自然切出，不要引起实体的攻击）</p></div>',6))])]))}},b=l(r,[["__scopeId","data-v-cc560f0e"]]);export{b as default};
